 public void Spell(MatchVisualEvent item){if(!enabled())return;SpellCount++;var text=new TextBlock{Text=playerLabel(item.Seat)+" 使用了 "+item.CardName,FontSize=10,FontWeight=FontWeights.Normal,Foreground=ink,TextAlignment=TextAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};var line=new Border{Child=text,Background=surface,Padding=new Thickness(5,2,5,2),MaxWidth=Math.Max(80,overlay.ActualWidth-24)};overlay.Children.Add(line);line.Measure(new Size(overlay.ActualWidth-24,30));Canvas.SetLeft(line,Math.Max(4,(overlay.ActualWidth-line.DesiredSize.Width)/2));Canvas.SetTop(line,Math.Max(22,overlay.ActualHeight/2-10));Fade(line,1000,0,()=>overlay.Children.Remove(line));}
 public void Discard(MatchVisualEvent item){if(!enabled())return;DiscardCount++;int generation=discardGeneration;int slot=0;while(discardSlots.Contains(slot))slot++;discardSlots.Add(slot);var text=new TextBlock{Text=playerLabel(item.Seat)+" 弃掉了 "+item.CardName,FontSize=10,FontWeight=FontWeights.Normal,Foreground=ink,TextAlignment=TextAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};var line=new Border{Child=text,Background=surface,Padding=new Thickness(5,1,5,1),MaxWidth=Math.Max(80,overlay.ActualWidth-24),ToolTip=text.Text};overlay.Children.Add(line);line.Measure(new Size(overlay.ActualWidth-24,30));Canvas.SetLeft(line,Math.Max(4,(overlay.ActualWidth-line.DesiredSize.Width)/2));Canvas.SetTop(line,Math.Max(24,overlay.ActualHeight-78-slot*17));var rise=new TranslateTransform();line.RenderTransform=rise;rise.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(0,-8,TimeSpan.FromMilliseconds(DiscardDurationMs)));Fade(line,DiscardDurationMs,0,()=>{overlay.Children.Remove(line);if(generation==discardGeneration)discardSlots.Remove(slot);});}
 public void Overdraw(MatchVisualEvent item,int delay){if(!enabled())return;OverdrawCount++;var content=new StackPanel();content.Children.Add(new TextBlock{Text=String.IsNullOrEmpty(item.CardName)?"卡牌背面":"费用 "+item.CardCost,FontSize=9,FontWeight=FontWeights.Normal,Foreground=ink});content.Children.Add(new TextBlock{Text=String.IsNullOrEmpty(item.CardName)?"卡牌背面":item.CardName,FontSize=12,FontWeight=FontWeights.Normal,Foreground=ink,TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,12,0,8)});if(!String.IsNullOrEmpty(item.CardName))content.Children.Add(new TextBlock{Text=String.IsNullOrEmpty(item.CardText)?"卡牌":item.CardText,FontSize=9,FontWeight=FontWeights.Normal,Foreground=ink,TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center});var card=new Border{Width=112,Height=148,Background=surface,BorderBrush=ink,BorderThickness=new Thickness(1),Padding=new Thickness(8),Child=content,Opacity=0,RenderTransform=new ScaleTransform(.82,.82,56,74)};overlay.Children.Add(card);card.Measure(new Size(112,148));Canvas.SetLeft(card,Math.Max(4,(overlay.ActualWidth-112)/2));Canvas.SetTop(card,Math.Max(4,(overlay.ActualHeight-148)/2));var scale=(ScaleTransform)card.RenderTransform;scale.BeginAnimation(ScaleTransform.ScaleXProperty,new DoubleAnimation(.82,1,TimeSpan.FromMilliseconds(180)){BeginTime=TimeSpan.FromMilliseconds(delay)});scale.BeginAnimation(ScaleTransform.ScaleYProperty,new DoubleAnimation(.82,1,TimeSpan.FromMilliseconds(180)){BeginTime=TimeSpan.FromMilliseconds(delay)});Fade(card,1520,delay,()=>overlay.Children.Remove(card));for(int n=0;n<8;n++){double angle=n*Math.PI/4;var shard=new Border{Width=10+n%3*4,Height=12+n%2*4,Background=ink,Opacity=0};overlay.Children.Add(shard);Canvas.SetLeft(shard,overlay.ActualWidth/2);Canvas.SetTop(shard,overlay.ActualHeight/2);var move=new TranslateTransform();shard.RenderTransform=move;move.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(0,Math.Cos(angle)*(30+n%3*8),TimeSpan.FromMilliseconds(650)){BeginTime=TimeSpan.FromMilliseconds(delay+420)});move.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(0,Math.Sin(angle)*(34+n%3*7),TimeSpan.FromMilliseconds(650)){BeginTime=TimeSpan.FromMilliseconds(delay+420)});shard.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,.8,TimeSpan.FromMilliseconds(70)){BeginTime=TimeSpan.FromMilliseconds(delay+420)});Fade(shard,650,delay+490,()=>overlay.Children.Remove(shard));}}
 public void Fatigue(MatchVisualEvent item,int delay){if(!enabled())return;FatigueCount++;var content=new StackPanel();content.Children.Add(new TextBlock{Text="疲劳",FontSize=14,FontWeight=FontWeights.Normal,Foreground=ink,TextAlignment=TextAlignment.Center});content.Children.Add(new TextBlock{Text=item.Amount>0?"−"+item.Amount:"未造成伤害",FontSize=12,FontWeight=FontWeights.Normal,Foreground=ink,TextAlignment=TextAlignment.Center});var frame=new Border{Child=content,Background=surface,BorderBrush=ink,BorderThickness=new Thickness(1),Padding=new Thickness(10,5,10,5),Opacity=0};overlay.Children.Add(frame);frame.Measure(new Size(120,52));Canvas.SetLeft(frame,Math.Max(4,(overlay.ActualWidth-frame.DesiredSize.Width)/2));Canvas.SetTop(frame,Math.Max(4,(overlay.ActualHeight-frame.DesiredSize.Height)/2));Fade(frame,1090,delay,()=>overlay.Children.Remove(frame));}
 public void Emote(MatchVisualEvent item,MatchVisualAnchor anchor){if(!enabled()||anchor==null)return;EmoteCount++;var text=new TextBlock{Text=item.UnitId>0?item.CardName:playerLabel(item.Seat)+"："+item.CardName,FontSize=11,FontWeight=FontWeights.Normal,Foreground=ink,TextWrapping=TextWrapping.Wrap};var bubble=new Border{Child=text,Background=surface,BorderBrush=ink,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(4),Padding=new Thickness(8,4,8,4),MaxWidth=Math.Max(80,Math.Min(280,overlay.ActualWidth-24))};overlay.Children.Add(bubble);bubble.Measure(new Size(bubble.MaxWidth,70));double x=Math.Max(4,Math.Min(overlay.ActualWidth-bubble.DesiredSize.Width-4,anchor.Bounds.X+anchor.Bounds.Width/2-bubble.DesiredSize.Width/2));bool above=anchor.Bounds.Y>overlay.ActualHeight/2;double y=above?anchor.Bounds.Y-bubble.DesiredSize.Height-6:anchor.Bounds.Bottom+6;Canvas.SetLeft(bubble,x);Canvas.SetTop(bubble,Math.Max(4,y));var tail=new System.Windows.Shapes.Polygon{Fill=surface,Stroke=ink,StrokeThickness=1,Points=above?new PointCollection{new Point(0,0),new Point(8,0),new Point(4,5)}:new PointCollection{new Point(0,5),new Point(8,5),new Point(4,0)}};overlay.Children.Add(tail);Canvas.SetLeft(tail,anchor.Bounds.X+anchor.Bounds.Width/2-4);Canvas.SetTop(tail,above?y+bubble.DesiredSize.Height-1:y-4);Fade(bubble,EmoteFadeDurationMs,EmoteFadeDelayMs,()=>overlay.Children.Remove(bubble));Fade(tail,EmoteFadeDurationMs,EmoteFadeDelayMs,()=>overlay.Children.Remove(tail));}
 public void Entrance(MatchVisualEvent item){if(!enabled()||!extraEffects()||item.CardName=="NEW1_030"&&!highEffects()||(item.CardName!="NEW1_030"&&item.CardName!="EX1_613"))return;EntranceCount++;ScreenShakeCount++;cinematicUntil=DateTime.UtcNow.AddMilliseconds(EntranceDurationMs);var move=new TranslateTransform();screen.RenderTransform=move;var shake=new DoubleAnimationUsingKeyFrames{Duration=TimeSpan.FromMilliseconds(EntranceDurationMs),FillBehavior=FillBehavior.Stop};for(int i=0;i<=40;i++)shake.KeyFrames.Add(new LinearDoubleKeyFrame(i==0||i==40?0:(i%2==0?3:-3),KeyTime.FromPercent(i/40.0)));move.BeginAnimation(TranslateTransform.XProperty,shake);if(item.CardName=="EX1_613")return;double width=Math.Max(80,overlay.ActualWidth),height=Math.Max(80,overlay.ActualHeight);for(int i=0;i<44;i++){var fire=new TextBlock{Text="火",FontSize=12+i%4*2,FontWeight=FontWeights.Normal,Foreground=new SolidColorBrush(Color.FromRgb(190,65,58)),Opacity=0};overlay.Children.Add(fire);double x=8+(i*73%((int)width-24)),y=35+(i*47%Math.Max(1,(int)height-105));Canvas.SetLeft(fire,x);Canvas.SetTop(fire,y);var rise=new TranslateTransform();fire.RenderTransform=rise;rise.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(22,-45,TimeSpan.FromMilliseconds(EntranceDurationMs)));Fade(fire,EntranceDurationMs,0,()=>overlay.Children.Remove(fire));}}
 public void MinionSpeech(MatchVisualEvent item,MatchVisualAnchor anchor){if(!enabled()||!extraEffects()||anchor==null)return;Emote(item,anchor);if(item.Kind=="fishing"&&extraEffects()&&anchor.Element!=null){CardShakeCount++;Shake(anchor.Element,2,0);}}
 public void Damage(MatchVisualEvent item,MatchVisualAnchor anchor,TimeSpan delay){if(!enabled()||item.Amount<=0||anchor==null)return;FloatCount++;int start=(int)delay.TotalMilliseconds;FrameworkElement target=anchor.Element;if(target==null&&anchor.Snapshot!=null){var ghost=new Image{Source=anchor.Snapshot,Width=anchor.Bounds.Width,Height=anchor.Bounds.Height};Canvas.SetLeft(ghost,anchor.Bounds.X);Canvas.SetTop(ghost,anchor.Bounds.Y);overlay.Children.Add(ghost);Fade(ghost,450,start,()=>overlay.Children.Remove(ghost));target=ghost;}
  var number=new TextBlock{Text="−"+item.Amount,FontSize=12,FontWeight=FontWeights.Normal,Foreground=ink,Background=surface,Padding=new Thickness(3,1,3,1),Opacity=0};overlay.Children.Add(number);double x=anchor.Bounds.X+anchor.Bounds.Width/2-12,y=anchor.Bounds.Y+Math.Max(2,anchor.Bounds.Height/3);Canvas.SetLeft(number,Math.Max(0,Math.Min(overlay.ActualWidth-34,x)));Canvas.SetTop(number,Math.Max(0,y));var lift=new TranslateTransform();number.RenderTransform=lift;number.BeginAnimation(UIElement.OpacityProperty,null);lift.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(0,-23,TimeSpan.FromMilliseconds(1000)){BeginTime=delay,FillBehavior=FillBehavior.Stop});Fade(number,1000,start,()=>overlay.Children.Remove(number));if(extraEffects()&&item.Amount>3&&target!=null){CardShakeCount++;Shake(target,2,start);}if(extraEffects()&&item.Amount>9){ScreenShakeCount++;if(IsPyroblast(item.Action))HeavyImpact();else if(DateTime.UtcNow>=cinematicUntil)Shake(screen,3,start);}}
 public void Clear(){ClearAttacks();ClearPyroblasts();ClearDeathFragments();ClearSpellCards();discardGeneration++;discardSlots.Clear();overlay.Children.Clear();screen.RenderTransform=Transform.Identity;cinematicUntil=DateTime.MinValue;}
}
public partial class PanelWindow {
 Canvas matchEffectsCanvas;IMatchVisualEffects matchEffects;readonly MatchVisualCursor visualCursor=new MatchVisualCursor(),drawVisualCursor=new MatchVisualCursor();
 readonly Dictionary<string,FrameworkElement> visualTargets=new Dictionary<string,FrameworkElement>();readonly Dictionary<string,MatchVisualAnchor> previousVisualTargets=new Dictionary<string,MatchVisualAnchor>();
 string visualAnchorSession;
 DateTime drawVisualNextUtc=DateTime.MinValue;string drawVisualSession;
 string VisualKey(int seat,int id){return seat+":"+id;}
 void BuildMatchEffects(){BuildPresentationLayout();matchEffectsCanvas=new Canvas{IsHitTestVisible=false,ClipToBounds=true,Visibility=Visibility.Collapsed};Put(shell,matchEffectsCanvas,4);Panel.SetZIndex(matchEffectsCanvas,30);matchEffects=new OfficeMatchVisualEffects(matchEffectsCanvas,shell,Ink,B("#F7F8FA"),()=>!minimal&&currentPage=="match"&&!awaitHandoff,()=>fullEffects&&!minimal,seat=>match==null?PlayerNames.Normalize(null,seat):match.PlayerLabel(seat),()=>HighEffects&&!minimal);}
 void CaptureMatchVisuals(){matchEffects.PrepareRedraw();PrepareMatchLayout();if(!minimal&&currentPage=="match")livePanel.UpdateLayout();previousVisualTargets.Clear();if(!minimal&&visualAnchorSession==match.VisualSession)foreach(var pair in visualTargets){var element=pair.Value;if(element.ActualWidth<1||element.ActualHeight<1)continue;var rect=element.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,element.ActualWidth,element.ActualHeight));var bitmap=new RenderTargetBitmap(Math.Max(1,(int)Math.Ceiling(element.ActualWidth)),Math.Max(1,(int)Math.Ceiling(element.ActualHeight)),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var context=drawing.RenderOpen())context.DrawRectangle(new VisualBrush(element){Stretch=Stretch.Fill},null,new Rect(0,0,element.ActualWidth,element.ActualHeight));bitmap.Render(drawing);previousVisualTargets[pair.Key]=new MatchVisualAnchor{Bounds=rect,Snapshot=bitmap};}visualTargets.Clear();visualAnchorSession=match.VisualSession;}
 void RegisterVisualTarget(int seat,int id,FrameworkElement target){visualTargets[VisualKey(seat,id)]=target;}
 void SyncMatchEffectsVisibility(){if(matchEffectsCanvas==null)return;bool show=currentPage=="match"&&!minimal&&!awaitHandoff;matchEffectsCanvas.Visibility=show?Visibility.Visible:Visibility.Collapsed;if(!show){drawVisualNextUtc=DateTime.MinValue;matchEffects.Clear();if(presentationLayout!=null)presentationLayout.Clear();}PresentMatchDrawVisuals();}
 MatchVisualAnchor ResolveAttackAnchor(int seat,int id,Dictionary<string,MatchVisualAnchor> old){
  string key=VisualKey(seat,id);MatchVisualAnchor prior;old.TryGetValue(key,out prior);FrameworkElement element;visualTargets.TryGetValue(key,out element);
  if(prior!=null)return new MatchVisualAnchor{Bounds=prior.Bounds,Snapshot=prior.Snapshot,Element=element};
  if(element==null)return null;return new MatchVisualAnchor{Bounds=element.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,element.ActualWidth,element.ActualHeight)),Element=element};
 }
 void PresentDrawVisuals(MatchVisualEvent[] events){foreach(var item in events){if(item.Kind!="burn"&&item.Kind!="fatigue")continue;int delay=Math.Max(0,(int)(drawVisualNextUtc-DateTime.UtcNow).TotalMilliseconds);if(item.Kind=="burn"){var visible=item;if(item.Seat!=matchViewSeat)visible=new MatchVisualEvent{Kind="burn",Seat=item.Seat};matchEffects.Overdraw(visible,delay);drawVisualNextUtc=DateTime.UtcNow.AddMilliseconds(delay+1520);}else{matchEffects.Fatigue(item,delay);drawVisualNextUtc=DateTime.UtcNow.AddMilliseconds(delay+1090);}}foreach(var item in events.Where(e=>e.Kind=="burn-speech")){FrameworkElement hero;if(visualTargets.TryGetValue(VisualKey(item.Seat,0),out hero)){var anchor=new MatchVisualAnchor{Element=hero,Bounds=hero.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,hero.ActualWidth,hero.ActualHeight))};matchEffects.Emote(new MatchVisualEvent{Seat=item.Seat,CardName="我的手牌已经满了！"},anchor);}}}
 void PresentMatchDrawVisuals(){if(match==null)return;if(drawVisualSession!=match.VisualSession){drawVisualSession=match.VisualSession;drawVisualNextUtc=DateTime.MinValue;matchEffects.Clear();}var events=drawVisualCursor.Take(match.VisualSession,match.VisualEvents,!minimal&&currentPage=="match"&&!awaitHandoff);if(events.Length>0)PresentDrawVisuals(events);}
 void PresentMatchVisuals(){var events=visualCursor.Take(match.VisualSession,match.VisualEvents,!minimal&&currentPage=="match"&&!awaitHandoff);SyncMatchEffectsVisibility();if(events.Length==0)return;var old=new Dictionary<string,MatchVisualAnchor>(previousVisualTargets);string session=match.VisualSession;bool playExtras=fullEffects&&!minimal;Dispatcher.BeginInvoke(new Action(()=>{if(match==null||match.VisualSession!=session||minimal||currentPage!="match")return;UpdateLayout();var attackHits=new HashSet<int>(events.Where(e=>e.Kind=="attack").Select(e=>e.Action));var pyroHits=new HashSet<int>(events.Where(e=>e.Kind=="pyroblast-impact").Select(e=>e.Action));var delays=new Dictionary<string,int>();var shattered=new HashSet<string>(events.Where(e=>e.Kind=="death").Select(e=>VisualKey(e.Seat,e.UnitId)));foreach(var item in events){if(item.Kind=="attack"){if(playExtras)matchEffects.Attack(item,ResolveAttackAnchor(item.Seat,item.UnitId,old),ResolveAttackAnchor(item.TargetSeat,item.TargetUnitId,old));continue;}if(item.Kind=="pyroblast"){if(playExtras&&HighEffects){FrameworkElement from,to;if(visualTargets.TryGetValue(VisualKey(item.Seat,0),out from)&&visualTargets.TryGetValue(VisualKey(item.TargetSeat,item.UnitId),out to))matchEffects.Pyroblast(item,new MatchVisualAnchor{Bounds=from.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,from.ActualWidth,from.ActualHeight))},new MatchVisualAnchor{Bounds=to.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,to.ActualWidth,to.ActualHeight))},Math.Max(0,MatchEngine.PyroblastAnimationMs-match.AnimationRemainingMs));}continue;}if(item.Kind=="pyroblast-impact"){matchEffects.PyroblastImpact(item);continue;}if(item.Kind=="hero-speech"){if(playExtras&&fullEffects){FrameworkElement hero;if(visualTargets.TryGetValue(VisualKey(item.Seat,0),out hero))matchEffects.Emote(item,new MatchVisualAnchor{Element=hero,Bounds=hero.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,hero.ActualWidth,hero.ActualHeight))});}continue;}if(item.Kind=="minion-speech"||item.Kind=="fishing"){if(!playExtras)continue;string speechKey=VisualKey(item.Seat,item.UnitId);FrameworkElement speaker;MatchVisualAnchor speechAnchor;old.TryGetValue(speechKey,out speechAnchor);if(visualTargets.TryGetValue(speechKey,out speaker))speechAnchor=new MatchVisualAnchor{Element=speaker,Bounds=speaker.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,speaker.ActualWidth,speaker.ActualHeight))};matchEffects.MinionSpeech(item,speechAnchor);continue;}if(item.Kind=="entrance"){if(playExtras)matchEffects.Entrance(item);continue;}if(item.Kind=="emote"){FrameworkElement hero;if(visualTargets.TryGetValue(VisualKey(item.Seat,0),out hero))matchEffects.Emote(item,new MatchVisualAnchor{Element=hero,Bounds=hero.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,hero.ActualWidth,hero.ActualHeight))});continue;}if(item.Kind=="discard"){matchEffects.Discard(item);continue;}if(item.Kind=="spell"){matchEffects.Spell(item);if(playExtras&&!String.IsNullOrEmpty(item.CardId)&&(localTest&&!lanMode||item.Seat!=matchViewSeat))matchEffects.SpellCard(item);continue;}if(item.Kind=="death"){if(playExtras&&fullEffects){MatchVisualAnchor deathAnchor;if(old.TryGetValue(VisualKey(item.Seat,item.UnitId),out deathAnchor))matchEffects.Death(item,deathAnchor,TimeSpan.FromMilliseconds(attackHits.Contains(item.Action)?OfficeMatchVisualEffects.AttackImpactMs:120),()=>presentationLayout.Complete(session,item.Sequence));}continue;}if(item.Kind!="damage")continue;string key=VisualKey(item.Seat,item.UnitId);FrameworkElement element;MatchVisualAnchor anchor;old.TryGetValue(key,out anchor);visualTargets.TryGetValue(key,out element);if(anchor==null&&element!=null)anchor=new MatchVisualAnchor{Bounds=element.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,element.ActualWidth,element.ActualHeight))};if(anchor==null)continue;anchor=new MatchVisualAnchor{Bounds=anchor.Bounds,Element=element,Snapshot=playExtras&&fullEffects&&shattered.Contains(key)?null:anchor.Snapshot};int hits;delays.TryGetValue(key,out hits);delays[key]=hits+1;matchEffects.Damage(item,anchor,TimeSpan.FromMilliseconds(pyroHits.Contains(item.Action)?0:attackHits.Contains(item.Action)?OfficeMatchVisualEffects.AttackImpactMs+hits*80:80+hits*80));}}));}
}
